{
  "title": "The Mirror Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver steps through a shattered window into the ruined city.",
      "visual_description": "A cracked mirror-like window in a crumbling wall, with a figure in a clear diving helmet and reflective coat stepping through, the city's broken spires and dangling royal banners reflected in his helmet.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer unrolls a map on a toppled statue.",
      "visual_description": "Mara kneels beside a fallen stone statue, spreading a large ink-stained map across its chest, her brass compass glowing faintly in the dim light from a nearby oil lamp.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers and warns of a cursed tower ahead.",
      "visual_description": "An oil lamp with a single glowing eye in its flame sits on a broken pillar, its light casting long shadows as it flickers urgently toward a twisted black tower in the distance.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scurries ahead to scout the castle gates.",
      "visual_description": "A small metal fox with a key-wind tail and blue glass eyes darts between rubble, pausing at the massive iron gates of the ruined castle, its gears faintly whirring.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver peers through a window into a guarded courtyard.",
      "visual_description": "The glass diver presses his helmet against a grimy window, his reflection showing armored figures patrolling inside, their visors down, while torn royal banners flap overhead.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara traces a secret path through the old marketplace.",
      "visual_description": "Mara carefully draws a line on her map with a quill, standing in a deserted market square filled with overturned carts and faded stalls, her breath visible in the cold air.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp warns of magic doors that lead to traps.",
      "visual_description": "The lamp's flame sputters and its eye narrows as it faces a row of ornate doors carved with glowing runes, each door slightly ajar revealing different shadowy interiors.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox triggers a hidden mechanism in the wall.",
      "visual_description": "The tin fox nuzzles a loose stone in a moss-covered wall, causing a click, as a section of the wall slides open to reveal a dark passage.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver swims through a mirror into a locked chamber.",
      "visual_description": "The glass diver's form distorts as he passes through a tall mirror into a dusty room, his helmet catching the light of a single candle on a desk.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara consults the Oracle Lamp at a crossroads.",
      "visual_description": "Mara holds the lamp up at a three-way fork in a narrow alley, its flame casting three different colored glows down each path, her map half-unrolled in her other hand.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The tin fox discovers a sleeping tax collector in a collapsed booth.",
      "visual_description": "The tin fox peeks into a half-crumbled tax booth, where a figure sleeps with a ledger book as a pillow, stamped papers stuck to his sleeves, undisturbed by the chaos.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver finds a hidden message scratched into a window pane.",
      "visual_description": "The glass diver traces his gloved finger over faint scratches on a window, forming words in the dust, his own reflection staring back from the dark glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Mara navigates through a maze of fallen royal banners.",
      "visual_description": "Mara pushes aside heavy, torn banners bearing faded crests, their fabric dragging on the ground as she steps over broken flagpoles, compass in hand.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The Oracle Lamp warns of armored patrols near the inner courtyard.",
      "visual_description": "The lamp's eye glows red, its flame shrinking, as it points with a flicker toward a courtyard where armored figures march in unison, their footsteps echoing.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector stirs but offers no help.",
      "visual_description": "The sleeping tax collector shifts and mumbles, a stamped paper fluttering from his sleeve, but he remains curled on his ledger pillow, eyes closed.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The tin fox leads the group to a hidden exit near the bridge.",
      "visual_description": "The tin fox scurries along a narrow ledge, its blue eyes reflecting the light of a distant bridge, as it signals with a soft whir to the others following behind.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver mirrors the group across the crumbling bridge.",
      "visual_description": "The glass diver stands at the center of the broken bridge, his helmet shining as he creates a reflective path through a series of window shards, guiding Mara and the others across.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The rescue escapes beyond the bridge into the mist.",
      "visual_description": "The group steps off the bridge into rolling mist, the ruined city fading behind them, the Oracle Lamp's flame steady, and the glass diver's helmet reflecting the last glimmer of the city's lights.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

